assert len(rows) == 44 and len({r["reportId"] for r in rows}) == 44
out = []
for r in rows:
    r, notes = guards.validate(r, Q[r["questionId"]], R[r["reportId"]]["comment"])
    if notes: print(r["reportId"], notes)
    if guards.detect_injection(R[r["reportId"]]["comment"]): r["flags"] = ["prompt_injection"]
    out.append(r)
out.sort(key=lambda x: x["reportId"])
json.dump(out, open(D / "results.json", "w"), indent=1, ensure_ascii=False)
from collections import Counter
print(Counter(r["route"] for r in out), Counter(r["verdict"] for r in out))

